# Converted to the revised ten-section template (plus section 11); content and tables carried from the previous version.
BOOK = 'Mark'
TESTAMENT = 'New Testament'
GENRE = 'gospels'
SUBTITLE = 'The Gospel of the Kingdom of God, the Servant, and the Ransom for Many'
SECTIONS = [(1, 'Book Setting & Program Identity', [('p', 'This section introduces you to the book by explaining who wrote it, who received it, and what was happening when it was written. It also shows you which of God’s programs the book belongs to — Israel’s prophetic program or the Body of Christ’s mystery program. Knowing the setting and the program identity helps you read the book in its proper context and understand how its teachings fit into the larger story of Scripture.'), ('p', 'Mark begins “The beginning of the gospel of Jesus Christ, the Son of God” (Mark 1:1). The Lord comes into Galilee “preaching the gospel of the kingdom of God,” teaches as one that had authority, calms the sea, is confessed by Peter as the Christ, comes to give his life “a ransom for many,” and is crucified under the superscription “THE KING OF THE JEWS” before the empty tomb (Mark 1:14–15, 22; 4:41; 8:29; 10:45; 15:26; 16:6).'), ('box', 'Program Identity:', 'The portions of Mark treated here belong to the Prophecy Program: the gospel Jesus preaches is the gospel of the kingdom of God, and the title written over the cross is the King of the Jews (Mark 1:14–15; 15:26). Its words on love and service are also placed in the Universal Truths Table.')]),
(2, 'Narrative Flow of Mark', [('p', 'This section gives you a simple walkthrough of how the book unfolds. Instead of diving into details right away, it shows the major movements in the book — how its message begins, how it develops, and how it builds toward its close. Seeing the flow of the book helps you understand the big picture before you study the individual passages.'), ('h3', 'Movement 1 — The Gospel of the Kingdom Begins (Ch. 1)'), ('p', 'The Lord comes into Galilee preaching the kingdom of God, calls fishers of men and teaches with authority (Mark 1:1, 14–15, 17, 22).'), ('h3', 'Movement 2 — Authority and Opposition (Chs. 2–6)'), ('p', 'The Lord calls sinners, speaks of the sabbath, and the wind and the sea obey him (Mark 2:17, 27; 3:35; 4:41).'), ('h3', 'Movement 3 — The Christ Confessed (Chs. 7–9)'), ('p', 'Peter answers, “Thou art the Christ,” and the Lord calls the cross-bearing path (Mark 8:29, 34; 9:35).'), ('h3', 'Movement 4 — The Road and the Ransom (Ch. 10)'), ('p', 'The Son of man comes to minister and to give his life a ransom for many (Mark 10:14, 45).'), ('h3', 'Movement 5 — Jerusalem and the Great Commandment (Chs. 11–13)'), ('p', 'The house of prayer is cleansed, and the first commandment is named (Mark 11:17; 12:30–31).'), ('h3', 'Movement 6 — The Cross and the Tomb (Chs. 14–16)'), ('p', 'The blood of the new testament, the King of the Jews on the cross, and the risen Lord (Mark 14:24; 15:26; 16:6, 15–16).')]),
(3, 'Program Themes in Mark', [('p', 'This section highlights the major ideas emphasized in the book — the big doctrinal themes that shape how Mark should be understood within Israel’s prophetic program. These themes are not verse-by-verse explanations; they are the book’s main emphases, the repeated ideas God wants readers to carry forward. Seeing these themes together helps you understand the book’s message before you look at the individual truths in the tables.'), ('ol', ['<b>The Gospel of the Kingdom of God</b> — “Jesus came into Galilee, preaching the gospel of the kingdom of God” (Mark 1:14).', '<b>The Time Fulfilled</b> — “The time is fulfilled, and the kingdom of God is at hand: repent ye, and believe the gospel” (Mark 1:15).', '<b>Fishers of Men</b> — “Come ye after me, and I will make you to become fishers of men” (Mark 1:17).', '<b>The Servant of All</b> — “If any man desire to be first, the same shall be last of all, and servant of all” (Mark 9:35).', '<b>The House of Prayer</b> — “My house shall be called of all nations the house of prayer” (Mark 11:17).', '<b>The King of the Jews</b> — “THE KING OF THE JEWS” (Mark 15:26).'])]),
(4, 'Christ in Mark', [('p', 'This section gathers what the book teaches about Christ — who He is, what He has done, and how He is presented. These statements help you see the book’s Christ-centered focus before you study the doctrinal truths in detail. By collecting these verses together, you get a clear picture of how Mark presents Christ.'), ('ol', ['<b>The Son of God</b> — “The beginning of the gospel of Jesus Christ, the Son of God” (Mark 1:1); Peter says, “Thou art the Christ” (Mark 8:29).', '<b>The Ransom for Many</b> — “The Son of man came not to be ministered unto, but to minister, and to give his life a ransom for many” (Mark 10:45).', '<b>The Blood of the New Testament</b> — “This is my blood of the new testament, which is shed for many” (Mark 14:24), reported as written.', '<b>He Is Risen</b> — “Ye seek Jesus of Nazareth, which was crucified: he is risen; he is not here” (Mark 16:6).'])]),
(5, 'Israel, the Law, and the Covenants in Mark', [('p', 'This section helps you see how Mark speaks about Israel, the law, and the covenants without mixing programs. Mark operates within Israel’s prophetic framework. By gathering these points together, this section shows you how to read Mark in its own setting — as an Israel-program book — while recognizing what it says (and does not say) about the Body of Christ.'), ('p', 'Mark reinforces Israel’s:'), ('ul', ['the gospel of the kingdom of God preached in Galilee (Mark 1:14–15)', 'the Christ confessed by Peter (Mark 8:29)', 'the King of the Jews written over the cross (Mark 15:26)', 'the house of prayer named from Isaiah, set in Jerusalem (Mark 11:17)']), ('p', 'All content belongs exclusively to the Prophecy Program.')]),
(6, 'Israel-Program Distinctions', [('p', 'This section highlights the teachings in Mark that belong uniquely to Israel’s prophetic program — truths rooted in prophecy, covenant promises, national identity, and God’s dealings with Israel. By gathering these together, this section helps you see how Mark contributes to Israel’s story without borrowing from the Body-of-Christ program.'), ('ul', ['The Gospel of the Kingdom of God — “preaching the gospel of the kingdom of God.” (Mark 1:14).', 'The Kingdom at Hand — “The time is fulfilled, and the kingdom of God is at hand: repent ye, and believe the gospel.” (Mark 1:15).', 'Peter’s Confession — “Thou art the Christ.” (Mark 8:29).', 'The Ransom for Many — “to give his life a ransom for many.” (Mark 10:45).', 'The Blood of the New Testament — “This is my blood of the new testament, which is shed for many.” (Mark 14:24).', 'The Superscription — “THE KING OF THE JEWS.” (Mark 15:26).', 'He Is Risen — “he is risen; he is not here.” (Mark 16:6).', 'Go Into All the World — “Go ye into all the world, and preach the gospel to every creature.” (Mark 16:15).', 'Believeth and Is Baptized — “He that believeth and is baptized shall be saved.” (Mark 16:16).'])]),
(7, 'Truths Table: What Mark Says', [('p', 'This table gathers the key statements, instructions, and teachings in Mark and shows which ones belong to Israel’s prophetic program. Each row lists a truth from the book, explains what it says, and identifies its program identity based on the prophetic setting. This helps you see, at a glance, what Mark teaches directly to Israel and keeps those truths separate from universal principles that apply more broadly.'), ('table', ['Category', 'Truth Revealed in Mark', 'Program Identity', 'Scripture'], [['The Gospel of the Kingdom of God', '“preaching the gospel of the kingdom of God.”', 'Israel / Kingdom / Prophecy Explicit Truth', 'Mark 1:14'], ['The Kingdom at Hand', '“The time is fulfilled, and the kingdom of God is at hand: repent ye, and believe the gospel.”', 'Israel / Kingdom / Prophecy Explicit Truth', 'Mark 1:15'], ['Peter’s Confession', '“Thou art the Christ.”', 'Israel / Kingdom / Prophecy Explicit Truth', 'Mark 8:29'], ['The Ransom for Many', '“to give his life a ransom for many.”', 'Israel / Kingdom / Prophecy Explicit Truth', 'Mark 10:45'], ['The Blood of the New Testament', '“This is my blood of the new testament, which is shed for many.”', 'Israel / Kingdom / Prophecy Explicit Truth', 'Mark 14:24'], ['The Superscription', '“THE KING OF THE JEWS.”', 'Israel / Kingdom / Prophecy Explicit Truth', 'Mark 15:26'], ['He Is Risen', '“he is risen; he is not here.”', 'Israel / Kingdom / Prophecy Explicit Truth', 'Mark 16:6'], ['Go Into All the World', '“Go ye into all the world, and preach the gospel to every creature.”', 'Israel / Kingdom / Prophecy Explicit Truth', 'Mark 16:15'], ['Believeth and Is Baptized', '“He that believeth and is baptized shall be saved.”', 'Israel / Kingdom / Prophecy Explicit Truth', 'Mark 16:16']], [20, 34, 26, 20])]),
(8, 'Universal Truths Table (All People, All Time)', [('p', 'This table gathers the truths in Mark that apply to everyone, not just Israel. These are principles rooted in God’s character — things that hold true across all programs and all ages. By separating these universal truths from Israel’s covenant-specific instructions, this section helps you see what Mark teaches all believers everywhere and what it teaches Israel in its own setting.'), ('table', ['Universal Truth', 'Description', 'Scripture'], [['The First Commandment', '“thou shalt love the Lord thy God with all thy heart, and with all thy soul, and with all thy mind, and with all thy strength.”', 'Mark 12:30'], ['Love of Neighbour', '“Thou shalt love thy neighbour as thyself.”', 'Mark 12:31'], ['Servant of All', '“the same shall be last of all, and servant of all.”', 'Mark 9:35'], ['All Things Possible', '“all things are possible to him that believeth.”', 'Mark 9:23'], ['What Defiles', '“the things which come out of him, those are they that defile the man.”', 'Mark 7:15']], [28, 48, 24])]),
(9, 'Program-Safe Application Grid', [('p', 'This section shows how to apply the teachings of Mark without mixing programs. The applications come from Israel’s prophetic story and from universal truths that apply to everyone. By keeping the applications tied to what the book actually says — and not borrowing Israel-program commands for the Body of Christ — this grid helps you respond to Mark in a way that is faithful to its setting, clear, and safe.'), ('ol', ['<b>Love God with everything</b> — Heart, soul, mind and strength (Mark 12:30).', '<b>Love your neighbour</b> — As yourself (Mark 12:31).', '<b>Serve others</b> — Last of all, and servant of all (Mark 9:35).', '<b>Believe Him</b> — All things are possible to him that believeth (Mark 9:23).', '<b>Guard the heart</b> — What comes out defiles (Mark 7:15).'])]),
(10, 'Teaching Outline for Mark', [('p', 'This outline gives you a teacher-ready structure for presenting the book. It follows the narrative movements and highlights the major themes, making it easy to teach Mark in classes, small groups, or personal study.'), ('olr', ['The Gospel of the Kingdom Begins (Ch. 1) — Repent and believe. <i>(Mark 1:1, 14–15, 17, 22)</i>', 'Authority and Opposition (Chs. 2–6) — The wind and the sea obey. <i>(Mark 2:17, 27; 4:41)</i>', 'The Christ Confessed (Chs. 7–9) — Thou art the Christ. <i>(Mark 7:15; 8:29, 34; 9:23, 35)</i>', 'The Road and the Ransom (Ch. 10) — A ransom for many. <i>(Mark 10:14, 45)</i>', 'Jerusalem and the Great Commandment (Chs. 11–13) — The first commandment. <i>(Mark 11:17; 12:30–31)</i>', 'The Cross and the Tomb (Chs. 14–16) — The King of the Jews, risen. <i>(Mark 14:24; 15:26; 16:6, 15–16)</i>'])]),
(11, 'Companion Usage and Study Suggestions', [('h3', 'How to Use This Companion in Personal Study'), ('p', 'This Companion is designed to walk alongside you as you read Mark, helping you see both the prophetic structure of the book and the timeless truths rooted in God’s character. Use it slowly, chapter by chapter, letting the narrative movements, themes, and universal truths deepen your understanding. The Program-Safe Applications will guide your heart toward service, love of God and neighbour, and faith in the Lord’s power without confusing Israel’s covenant commands with the Body of Christ’s calling today.'), ('h3', 'How to Use This Companion in Small Groups or Classes'), ('p', 'This Companion provides a clear, structured framework that makes teaching Mark simple and accessible. Each section gives you ready-to-use material: narrative movements for overview, prophecy-program themes for doctrinal clarity, universal truths for discussion, and a pastoral teaching outline for weekly lessons. Use the tables to help your group distinguish Israel’s covenant identity from universal principles, and use the Program-Safe Application Grid to foster meaningful, Christ-centered conversation.'), ('h3', 'How This Companion Fits Within the Acts Overlap Theology Series'), ('p', 'This Companion is part of a larger series designed to help believers read every book of Scripture without blurring God’s prophetic program for Israel and His mystery program for the Body of Christ. Within the Acts Overlap Theology Series, Mark stands firmly in Israel’s covenant story, yet it still reveals universal truths that shape Christian character today. This Companion shows you how to honor the book’s prophetic context while drawing out the timeless principles that apply to all believers in every age.')])]

# Place in God's Storyline (Master Standard v1.155): last item of Section 1
from storyline import S as _STORY
SECTIONS[0][2].append(('p', '<b>Place in God’s Storyline.</b> ' + _STORY['mark'][1]))
